    border-radius: 4px; background: var(--color-primary-500);
  }
  .trello-mark i { display: block; border-radius: 1px; background: #fff; }
  .trello-mark i:last-child { height: 68%; }
  .trello-wordmark { font-size: 20px; font-weight: 700; letter-spacing: -0.5px; }
  .trello-nav { display: flex; align-items: center; gap: 4px; }
  .trello-nav span { padding: 7px 8px; border-radius: var(--radius-sm); color: var(--text-secondary); font-size: 13px; }
  .trello-nav span:hover { background: var(--bg-subtle); color: var(--text-primary); }
  .trello-create { margin-left: 2px; height: 32px; }
  .trello-account {
    margin-left: auto; width: 30px; height: 30px; border-radius: var(--radius-full);
    background: linear-gradient(135deg, var(--label-orange), var(--label-purple));
    border: 2px solid var(--bg-base); box-shadow: 0 0 0 1px var(--border-default);
  }
  .trello-hero {
    padding: clamp(36px, 6vw, 72px) clamp(24px, 7vw, 88px) 56px;
    display: grid;
    grid-template-columns: minmax(280px, .82fr) minmax(480px, 1.18fr);
    align-items: center;
    gap: clamp(32px, 6vw, 80px);
    background: var(--bg-base);
  }
  .trello-eyebrow {
    display: inline-flex; align-items: center; gap: 8px;
    color: var(--color-primary-600); font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  }
  .trello-eyebrow::before { content: ''; width: 24px; height: 4px; border-radius: 4px; background: var(--label-green); }
  .trello-copy h1 {
    max-width: 570px; margin: 16px 0;
    color: var(--text-primary); font-size: clamp(38px, 5vw, 62px); line-height: 1.04; letter-spacing: -.035em;
  }
  .trello-copy p { max-width: 540px; margin: 0; color: var(--text-secondary); font-size: 17px; line-height: 1.65; }
