  .feature-icon::before { content: ''; width: 22px; height: 17px; border: 2px solid currentColor; border-radius: 3px; box-shadow: inset 6px 0 0 transparent; }
  .feature-card:nth-child(2) .feature-icon { background: var(--color-success-bg); color: var(--color-success-fg); }
  .feature-card:nth-child(2) .feature-icon::before { width: 20px; height: 4px; border: 0; border-radius: 3px; background: currentColor; box-shadow: 0 7px 0 currentColor, 0 14px 0 currentColor; }
  .feature-card:nth-child(3) .feature-icon { background: var(--color-warning-bg); color: var(--color-warning-fg); }
